import assert from 'node:assert/strict';
import {readFile,writeFile,mkdir}from'node:fs/promises';
import{resolve}from'node:path';import{randomUUID,createHash}from'node:crypto';
import{Persistence,backup,restore}from'@tileset/persistence';
import{StudioService}from'../../../apps/api/dist/studio-service.js';
import{createApplication}from'../../../apps/api/dist/app.js';import{parseConfig}from'../../../apps/api/dist/config.js';
import{PrismaClient}from'../../../apps/api/node_modules/@prisma/client/default.js';
process.loadEnvFile('.env');const stage='.local/step07/fix-round4/final',resources=JSON.parse(await readFile('apps/api/dist/resources/studio.json','utf8'));const original=JSON.parse(await readFile('.local/step07/fix-round4/broken-counterexample-fixture.json','utf8')),url=new URL(process.env.DATABASE_URL);url.pathname='/'+original.database;assert.equal(url.port,'55476');const old=new Persistence(url.href,original.assets,resources.profile),admin=new PrismaClient(),base=resolve('.local/step07/fix-round4/broken-recovery-'+randomUUID()),report={sourceSHA:resources.context.commit,originalFixture:original,originalModified:false,scope:'Recoverable backup of own synthetic ef30 counterexample; fresh owned DB/root clone; protected HTTP conversion only on clone; no valuable/batch writes'};
let restored,application;
try{await mkdir(base);const before=await old.db.studioJob.findUniqueOrThrow({where:{id:original.job}});assert.equal(before.state,'COMPLETED');assert.equal(await old.db.finalExport.count({where:{buildId:original.build}}),0);const manifest=await old.storage.buildFiles(original.build),originalSha=createHash('sha256').update(manifest['manifest.json']).digest('hex');const backupDir=base+'/backup';report.backup=await backup(old,backupDir,'/opt/homebrew/opt/postgresql@14/bin');
 const db='tileset_step07_r4_recovery_'+randomUUID().replaceAll('-','');await admin.$executeRawUnsafe(`CREATE DATABASE "${db}"`);url.pathname='/'+db;const target=base+'/restored-assets';restored=new Persistence(url.href,target,resources.profile);await restore(restored,backupDir,'/opt/homebrew/opt/postgresql@14/bin');await restored.close();restored=null;
 const config=parseConfig({...process.env,DATABASE_URL:url.href,NODE_ENV:'production',API_PORT:'4376',WEB_PORT:'5276'}),service=new StudioService(config,resources,target);application=await createApplication(config,service);await application.app.listen(4376,'127.0.0.1');const endpoint=`http://127.0.0.1:4376/api/projects/${original.project}/builds/${original.build}`;assert.equal((await fetch(endpoint+'/download')).status,409);const converted=await fetch(endpoint+'/export',{method:'POST',headers:{Origin:'http://127.0.0.1:4376','X-Tileset-Client':'local-v1','Content-Type':'application/json'},body:'{}'});assert.equal(converted.status,200);assert.equal(await service.store.db.finalExport.count({where:{buildId:original.build}}),1);const zip=await fetch(endpoint+'/download');assert.equal(zip.status,200);const bytes=new Uint8Array(await zip.arrayBuffer()),sha=createHash('sha256').update(bytes).digest('hex');assert.equal(zip.headers.get('x-content-sha256'),sha);assert.equal(createHash('sha256').update((await service.store.storage.buildFiles(original.build))['manifest.json']).digest('hex'),originalSha);
 assert.deepEqual(await old.db.studioJob.findUniqueOrThrow({where:{id:original.job}}),before);assert.equal(await old.db.finalExport.count({where:{buildId:original.build}}),0);report.clone={database:db,assets:target,convertedStatus:converted.status,finalExports:1,zipSHA256:sha,internalManifestUnchanged:originalSha,jobAfter:await service.store.db.studioJob.findUniqueOrThrow({where:{id:original.job}})};await writeFile(base+'/recovered-standard.zip',bytes);report.backupRetained=backupDir;
}finally{await application?.close();await restored?.close();await old.close();await admin.$disconnect();await writeFile(stage+'/broken-recovery-clone.json',JSON.stringify(report,null,2)+'\n');}console.log('OWN_SYNTHETIC_BROKEN_FIXTURE_BACKUP_CLONE_PROTECTED_RECOVERY_PASS');
